#!/usr/bin/env bash
# Self-contained builder for a context generated by build_headless_scorer.py.
set -euo pipefail
CONTEXT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "${CONTEXT_DIR}/build-inputs.env"
# A failed rebuild must not leave a previous success receipt looking current.
rm -f "${CONTEXT_DIR}/runtime-validation.json" "${CONTEXT_DIR}/image-receipt.txt"
DOCKER=(docker --context "${DOCKER_CONTEXT}")
BUILD_ARGS=()
for key in EVAL_BASE_IMAGE NODE_RUNTIME_IMAGE CODEX_VERSION DSH_VERSION CLAUDE_CODE_VERSION NPM_REGISTRY PIP_INDEX_URL DEBIAN_MIRROR DEBIAN_SECURITY_MIRROR; do
  BUILD_ARGS+=(--build-arg "${key}=${!key}")
done
# Proxy values are supplied at invocation, never persisted to the prepared context.
if [[ -n "${HTTP_PROXY_INNER:-}" ]]; then
  BUILD_ARGS+=(--build-arg "HTTP_PROXY=${HTTP_PROXY_INNER}" --build-arg "http_proxy=${HTTP_PROXY_INNER}")
fi
if [[ -n "${HTTPS_PROXY_INNER:-}" ]]; then
  BUILD_ARGS+=(--build-arg "HTTPS_PROXY=${HTTPS_PROXY_INNER}" --build-arg "https_proxy=${HTTPS_PROXY_INNER}")
fi
BASE_TAG="${IMAGE_TAG}"
if [[ "${WITH_OFFICE}" == 1 ]]; then BASE_TAG="${IMAGE_TAG}-runtime"; fi
"${DOCKER[@]}" build --progress=plain "${BUILD_ARGS[@]}" \
  --file "${CONTEXT_DIR}/Dockerfile" --tag "${BASE_TAG}" "${CONTEXT_DIR}"
if [[ "${WITH_OFFICE}" == 1 ]]; then
  "${DOCKER[@]}" build --progress=plain "${BUILD_ARGS[@]}" \
    --build-arg "SCORER_BASE_IMAGE=${BASE_TAG}" \
    --file "${CONTEXT_DIR}/native-office.Dockerfile" --tag "${IMAGE_TAG}" "${CONTEXT_DIR}"
fi
# Recheck the finished image without network, credentials, socket or host mounts.
VALIDATION_ARGS=(--claude-code-version "${CLAUDE_CODE_VERSION}")
if [[ "${WITH_OFFICE}" == 1 ]]; then VALIDATION_ARGS+=(--office); fi
"${DOCKER[@]}" run --rm --network none --entrypoint /opt/scoring-runtime/bin/python \
  "${IMAGE_TAG}" /opt/validate-scorer-runtime.py \
  --codex-version "${CODEX_VERSION}" --dsh-version "${DSH_VERSION}" \
  "${VALIDATION_ARGS[@]}" > "${CONTEXT_DIR}/runtime-validation.json.tmp"
mv "${CONTEXT_DIR}/runtime-validation.json.tmp" "${CONTEXT_DIR}/runtime-validation.json"
"${DOCKER[@]}" image inspect --format '{{json .Id}} {{json .Architecture}} {{json .Config.Labels}}' \
  "${IMAGE_TAG}" > "${CONTEXT_DIR}/image-receipt.txt"
echo "OK: ${IMAGE_TAG} (offline validation passed)"
echo "Receipts: ${CONTEXT_DIR}/runtime-validation.json, image-receipt.txt, build-manifest.json"
# Backend defaults are selected separately in scoring-image management.
echo "Backend .env: WCB_E2E_SCORING_IMAGES={\"codex\":\"${IMAGE_TAG}\",\"deepseek-harness\":\"${IMAGE_TAG}\",\"claudecode\":\"${IMAGE_TAG}\"}"
